WITH with_latest AS (SELECT s.*, latest.transaction_txn_time, latest.transaction_merchant FROM accounts s JOIN LATERAL (SELECT c.txn_time AS transaction_txn_time, c.merchant AS transaction_merchant FROM transactions c WHERE c.account_id = s.id AND c.txn_time <= s.opened_date ORDER BY c.txn_time DESC, c.id DESC LIMIT 1) latest ON TRUE) SELECT CASE WHEN balance >= 79000 THEN 'HIGH' ELSE 'LOW' END AS balance_tier, (UNIX_TIMESTAMP(MAX(transaction_txn_time)) - UNIX_TIMESTAMP(MIN(transaction_txn_time))) / 60 AS span_minutes, SORT_ARRAY(COLLECT_SET(transaction_merchant)) AS transaction_merchant_list, STDDEV_SAMP(balance) AS balance_stddev FROM with_latest GROUP BY CASE WHEN balance >= 79000 THEN 'HIGH' ELSE 'LOW' END
